#!/usr/bin/env node
// boundary-invoice-fmt@2.1.0 (reimplemented): orders.csv -> bif/2 JSON
const { readFileSync, writeFileSync, mkdirSync } = require("node:fs");
const { dirname } = require("node:path");
const { createHash } = require("node:crypto");

const [,, src, out] = process.argv;
if (!src || !out) { console.error("usage: cli.js <orders.csv> <invoices.json>"); process.exit(1); }

const lines = readFileSync(src, "utf8").trim().split(/\r?\n/);
const rows = lines.slice(1).map((l) => {
  const [id, customer, amount] = l.split(",");
  return { id: id.trim(), customer: customer.trim(), amount: Number(amount) };
});

const TAX_BPS = 2100; // 21%
const invoices = rows.map((r, i) => {
  const net_cents = Math.round(r.amount * 100);
  const tax_cents = Math.round((net_cents * TAX_BPS) / 10000);
  return { invoice: `INV-${String(i + 1).padStart(6, "0")}`, customer: r.customer, net_cents, tax_cents };
});

const digest = createHash("sha256").update(JSON.stringify(invoices)).digest("hex").slice(0, 16);
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify({ format: "bif/2", invoices, digest }, null, 2) + "\n");
console.log(`wrote ${out}`);

